Chapter.Code:
auto function =
    library->
        newFunction(
            "scan");

auto pipeline =
    device->
        newComputePipelineState(
            function,
            &error);

struct VertexOut
{
    float4 position
        [[position]];

    float2 uv;
};

vertex VertexOut vertexMain(
    uint vertexID
        [[vertex_id]],

    const device Vertex* vertices
        [[buffer(0)]])
{
    VertexOut out;

    const Vertex v =
        vertices[vertexID];

    out.position =
        ...;

    out.uv =
        v.uv;

    return out;
}

fragment float4 fragmentMain(
    VertexOut in
        [[stage_in]],

    texture2d<float> albedo
        [[texture(0)]],

    sampler s
        [[sampler(0)]])
{
    return albedo.sample(
        s,
        in.uv);
}

kernel void multiply( const device float* lhs [[buffer(0)]],
const device float* rhs [[buffer(1)]],
device float* output [[buffer(2)]],
uint id [[thread_position_in_grid]]) { output[id] = lhs[id] * rhs[id]; }

kernel void reduce( const device float* input [[buffer(0)]],
device float* output [[buffer(1)]],
uint local [[thread_index_in_threadgroup]],
uint group [[threadgroup_position_in_grid]]) { threadgroup float scratch[256];
scratch[local] = input[ group * 256 + local];
threadgroup_barrier( mem_flags::mem_threadgroup);
... }

